{"command": "python3 << 'EOF'
from rdkit import Chem

product = "CC(C)(C)OC(=O)Nc1nc(-c2ccc(S(C)(=O)=O)cc2)ns1"
mol = Chem.MolFromSmiles(product)

if mol:
    print("Product SMILES valid")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find bonds to pyrazole ring
    for bond in mol.GetBonds():
        if bond.GetBeginAtomIdx() < 10 and bond.GetEndAtomIdx() >= 10:
            begin = mol.GetAtomWithIdx(bond.GetBeginAtomIdx())
            end = mol.GetAtomWithIdx(bond.GetEndAtomIdx())
            print(f"Bond: {begin.GetSymbol()}({bond.GetBeginAtomIdx()})-{end.GetSymbol()}({bond.GetEndAtomIdx()})")
else:
    print("Invalid SMILES")
EOF
"}

